<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{listColumns,type CmsColumn}from'../../api/columns';import{listPages,type CmsPage}from'../../api/pages';import{createNavigation,deleteNavigation,listNavigations,updateNavigation,type CmsNavigation,type NavigationDraft,type NavigationPosition,type NavigationTargetType}from'../../api/navigation';const items=ref<CmsNavigation[]>([]),columns=ref<CmsColumn[]>([]),pages=ref<CmsPage[]>([]),loading=ref(false),dialogVisible=ref(false),saving=ref(false),editingId=ref<number|null>(null);const form=reactive<NavigationDraft>({name:'',position:'MAIN',category:null,targetType:'COLUMN',targetColumnId:null,targetPageId:null,targetUrl:null,parentId:null,openMode:'DEFAULT',sortOrder:0,enabled:true});const parentOptions=computed(()=>items.value.filter(i=>i.id!==editingId.value)),positionOptions:Array<{value:NavigationPosition;label:string}>=[{value:'MAIN',label:'主导航'},{value:'SERVICE',label:'服务入口'},{value:'SITE',label:'网站导航'}],targetOptions:Array<{value:NavigationTargetType;label:string}>=[{value:'HOME',label:'网站首页'},{value:'COLUMN',label:'本站栏目'},{value:'PAGE',label:'固定页面'},{value:'LINK',label:'链接地址'},{value:'PLACEHOLDER',label:'占位菜单'}];onMounted(refresh);async function refresh(){loading.value=true;try{[items.value,columns.value,pages.value]=await Promise.all([listNavigations(),listColumns(),listPages()])}catch(e){ElMessage.error(msg(e))}finally{loading.value=false}}function openCreate(){editingId.value=null;Object.assign(form,{name:'',position:'MAIN',category:null,targetType:'COLUMN',targetColumnId:null,targetPageId:null,targetUrl:null,parentId:null,openMode:'DEFAULT',sortOrder:0,enabled:true});dialogVisible.value=true}function openEdit(r:CmsNavigation){editingId.value=r.id;Object.assign(form,{name:r.name,position:r.position,category:r.category,targetType:r.targetType,targetColumnId:r.targetColumnId,targetPageId:r.targetPageId,targetUrl:r.targetUrl,parentId:r.parentId,openMode:r.openMode,sortOrder:r.sortOrder,enabled:r.enabled});dialogVisible.value=true}async function save(){saving.value=true;try{editingId.value==null?await createNavigation({...form}):await updateNavigation(editingId.value,{...form});dialogVisible.value=false;await refresh()}catch(e){ElMessage.error(msg(e))}finally{saving.value=false}}async function toggle(r:CmsNavigation,enabled:boolean){try{await updateNavigation(r.id,{...r,enabled});await refresh()}catch(e){ElMessage.error(msg(e));await refresh()}}async function remove(r:CmsNavigation){try{await ElMessageBox.confirm(`确定删除导航“${r.name}”吗？`,'删除导航',{type:'warning'});await deleteNavigation(r.id);await refresh()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(msg(e))}}function target(r:CmsNavigation){if(r.targetType==='HOME')return'网站首页';if(r.targetType==='PLACEHOLDER')return'占位';if(r.targetType==='LINK')return r.targetUrl||'-';if(r.targetType==='PAGE')return pages.value.find(p=>p.id===r.targetPageId)?.name||`页面 #${r.targetPageId}`;return columns.value.find(c=>c.id===r.targetColumnId)?.name||`栏目 #${r.targetColumnId}`}const msg=(e:unknown)=>e instanceof Error?e.message:'操作失败'</script><template><main class="admin-shell"><header class="page-header"><div><p class="eyebrow">网站导航</p><h1>导航管理</h1><p class="subtitle">菜单与栏目分离，可指向首页、栏目、固定页面、链接或占位入口。</p></div><el-button data-testid="add-navigation" type="primary" @click="openCreate">新增导航</el-button></header><el-card shadow="never"><el-table v-loading="loading" :data="items" row-key="id"><el-table-column prop="name" label="导航名称"/><el-table-column prop="position" label="位置" width="100"/><el-table-column label="目标"><template #default="s">{{target(s.row)}}</template></el-table-column><el-table-column prop="sortOrder" label="排序" width="80"/><el-table-column label="状态" width="130"><template #default="s"><el-switch :model-value="s.row.enabled" :data-testid="`navigation-enabled-${s.row.id}`" @change="v=>toggle(s.row,v===true)"/></template></el-table-column><el-table-column label="操作" width="150"><template #default="s"><el-button :data-testid="`navigation-edit-${s.row.id}`" link type="primary" @click="openEdit(s.row)">编辑</el-button><el-button :data-testid="`navigation-delete-${s.row.id}`" link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="dialogVisible" :title="editingId==null?'新增导航':'编辑导航'" width="620px"><el-form label-width="100px"><el-form-item label="导航名称"><el-input v-model="form.name" placeholder="请输入导航名称"/></el-form-item><el-form-item label="展示位置"><el-select v-model="form.position" style="width:100%"><el-option v-for="o in positionOptions" :key="o.value" :label="o.label" :value="o.value"/></el-select></el-form-item><el-form-item label="上级菜单"><el-select v-model="form.parentId" clearable style="width:100%"><el-option v-for="i in parentOptions" :key="i.id" :label="i.name" :value="i.id"/></el-select></el-form-item><el-form-item label="目标类型"><el-select v-model="form.targetType" style="width:100%"><el-option v-for="o in targetOptions" :key="o.value" :label="o.label" :value="o.value"/></el-select></el-form-item><el-form-item v-if="form.targetType==='COLUMN'" label="目标栏目"><el-select data-testid="navigation-column-select" v-model="form.targetColumnId" filterable style="width:100%"><el-option v-for="c in columns" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item v-if="form.targetType==='PAGE'" label="目标页面"><el-select v-model="form.targetPageId" filterable style="width:100%"><el-option v-for="p in pages" :key="p.id" :label="p.name" :value="p.id"/></el-select></el-form-item><el-form-item v-if="form.targetType==='LINK'" label="目标地址"><el-input v-model="form.targetUrl" placeholder="站内路径或 HTTP(S) 地址"/></el-form-item><el-form-item label="打开方式"><el-select v-model="form.openMode" style="width:100%"><el-option label="按目标默认" value="DEFAULT"/><el-option label="当前窗口" value="SAME_WINDOW"/><el-option label="新窗口" value="NEW_WINDOW"/></el-select></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortOrder"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.enabled"/></el-form-item></el-form><template #footer><el-button @click="dialogVisible=false">取消</el-button><el-button data-testid="save-navigation" type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></main></template>
